sys_ui_script.script:
function aiab_header_chat_injector() {
  try {
    load();
  } catch (e) {
    console.log('AIAB Header Injector Error: ' + e);
  }

  function load() {
    var top = window.top;
    var id = 'aiab-header-btn';
    var url = top.location.pathname;

    // Detect UI type
    var isWorkspace = url.indexOf('/now/') === 0;
    var isPolaris = top.NOW && top.NOW.hasOwnProperty('isPolarisWrapper') && top.NOW.isPolarisWrapper;
    var isUI16 = !isPolaris && !isWorkspace && top.hasOwnProperty('$j') && top.$j('.navpage-header-content').length > 0;

    if (typeof top.aiab_header_loaded != 'undefined') {
      return;
    }
    top.aiab_header_loaded = true;

    if (top.window.document.querySelector('#' + id)) {
      return;
    }

    if (isWorkspace) {
      injectWorkspace();
    } else if (isPolaris) {
      injectPolaris();
    } else if (isUI16) {
      injectUI16();
    }

    function injectWorkspace() {
      // Workspace uses different selectors - wait for header to load
      var attempts = 0;
      var maxAttempts = 50;

      function tryInject() {
        attempts++;

        // Try multiple Workspace header selectors
        var headerSelectors = [
          'now-record-header',
          'now-modal-header',
          'now-header',
          'sn-workspace-header',
          '[data-testid="workspace-header"]',
          '.workspace-header'
        ];

        var target = null;
        for (var i = 0; i < headerSelectors.length; i++) {
          target = top.document.querySelector(headerSelectors[i]);
          if (target) break;
        }

        if (!target && attempts < maxAttempts) {
          setTimeout(tryInject, 200);
          return;
        }

        if (!target) {
          console.log('AIAB: Could not find Workspace header after ' + maxAttempts + ' attempts');
          return;
        }

        // Check if already injected
        if (target.shadowRoot && target.shadowRoot.querySelector('#' + id)) {
          return;
        }

        // Create button for Workspace
        var button = document.createElement('button');
        button.id = id;
        button.innerHTML = '💬 AI';
        button.style.cssText = 'margin-left:8px;padding:4px 8px;background:#4a90e2;color:white;border:none;border-radius:4px;cursor:pointer;font-size:12px;';
        button.onclick = function() {
          aiab_toggle_chat();
        };

        // Try to inject into shadow DOM or regular DOM
        if (target.shadowRoot) {
          var headerActions = target.shadowRoot.querySelector('[slot="actions"]') ||
                             target.shadowRoot.querySelector('.header-actions') ||
                             target.shadowRoot.querySelector('.actions');
          if (headerActions) {
            headerActions.appendChild(button);
          } else {
            target.shadowRoot.appendChild(button);
          }
        } else {
          target.appendChild(button);
        }

        console.log('AIAB: Loaded for Workspace');
      }

      tryInject();
    }

    function injectPolaris() {
      var path = [
        'macroponent-f51912f4c700201072b211d4d8c26010', 'shadowRoot',
        'sn-polaris-layout', 'shadowRoot',
        'sn-polaris-header', 'shadowRoot'
      ];

      var button = $j(
        '<span' +
        ' role="button"' +
        ' tabindex="0"' +
        ' id="' + id + '" aria-label="AI in a Box"' +
        ' class="contextual-zone-button"' +
        ' style="margin-inline-start: 0.5rem; cursor:pointer;"' +
        ' title="AI in a Box Chat">' +
          '<now-icon class="contextual-zone-icon" icon="comment-outline" dir="ltr"></now-icon>' +
        '</span>');

      button.on('click', function() {
        toggleChat();
      });

      var target = findElement(path.concat('.search-container'), top.window.document)
                || findElement(path.concat('.polaris-search'), top.window.document);

      if (typeof target === 'string') {
        console.log(target);
      } else if (target) {
        target = $j(target);
        if (target.hasClass('search-container')) {
          target.prepend(button);
        } else {
          target.after(button);
        }
        console.log('AIAB: Loaded for Next Experience');
      }
    }

    function injectUI16() {
      var buttonHtml = '<button id="' + id + '" class="btn btn-icon icon-chat"' +
        ' title="AI in a Box Chat" onclick="aiab_toggle_chat()" style="margin-left:5px;">' +
        '<span class="sr-only">AI Chat</span>' +
      '</button>';

      top.$j('#sysparm_search').parents('div.navpage-header-content').first().after(buttonHtml);

      window.aiab_toggle_chat = toggleChat;
      console.log('AIAB: Loaded for UI16');
    }

    function findElement(path, el) {
      path.forEach(function (dir, i) {
        if (!el) return;
        el = dir == 'shadowRoot' ? el.shadowRoot : el.querySelector(dir);
        if (!el) {
          return 'AIAB could not find element ' + i + ' (' + dir + ') for path ' + path.join('/');
        }
      });
      return el;
    }
  }

  // Chat panel state
  var chatPanel = null;
  var isOpen = false;
  var currentRecord = null;

  function getRecordContext() {
    // Try multiple ways to get record context
    var table, sysId, display;

    // Method 1: g_form (classic forms)
    if (typeof g_form !== 'undefined' && g_form.getTableName) {
      table = g_form.getTableName();
      sysId = g_form.getUniqueValue();
      display = g_form.getValue('number') || '';
    }
    // Method 2: URL parameters (Workspace)
    else {
      var params = new URLSearchParams(window.location.search);
      table = params.get('table') || params.get('sys_target');
      sysId = params.get('sys_id');

      // Try to extract from URL path for Workspace
      var pathMatch = window.location.pathname.match(/\/now\/([^\/]+)\/([^\/]+)/);
      if (pathMatch) {
        table = table || pathMatch[1];
        sysId = sysId || pathMatch[2];
      }
    }

    if (!table) return null;

    return {
      table: table,
      sysId: sysId || '',
      display: display || ''
    };
  }

  function buildChatUrl(record) {
    var url = '/aiab?id=aiab_chat';
    if (record) {
      url += '&record_table=' + encodeURIComponent(record.table);
      url += '&record_sys_id=' + encodeURIComponent(record.sysId);
      if (record.display) {
        url += '&record_display=' + encodeURIComponent(record.display);
      }
    }
    return url;
  }

  function createChatPanel() {
    if (chatPanel) return;

    chatPanel = top.document.createElement('iframe');
    chatPanel.id = 'aiab-chat-panel';
    chatPanel.style.cssText = 'position:fixed;top:50px;right:-420px;width:420px;height:calc(100vh - 50px);' +
      'border:none;z-index:9999;background:white;box-shadow:-2px 0 10px rgba(0,0,0,0.2);' +
      'transition:right 0.3s ease-in-out;';

    var record = getRecordContext();
    chatPanel.src = buildChatUrl(record);

    top.document.body.appendChild(chatPanel);
  }

  window.aiab_toggle_chat = function() {
    createChatPanel();

    var record = getRecordContext();
    if (record && (!currentRecord || 
        record.table !== currentRecord.table || 
        record.sysId !== currentRecord.sysId)) {
      currentRecord = record;
      chatPanel.src = buildChatUrl(record);
    }

    isOpen = !isOpen;
    if (isOpen) {
      chatPanel.style.right = '0';
    } else {
    chatPanel.style.right = '-420px';
    }
  };
}

if (typeof jQuery === 'function') {
  jQuery(document).ready(aiab_header_chat_injector);
}
